package run.ikaros.planning; import java.time.Instant; import java.util.UUID; import org.springframework.stereotype.Service; import reactor.core.publisher.Flux; import reactor.core.publisher.Mono; import run.ikaros.common.ConflictException; import run.ikaros.common.NotFoundException;
@Service public class PersistentPlanningTaskAssignmentService implements PlanningTaskAssignmentService {private final PlanningTaskRepository tasks;private final PlanningProjectMemberRepository members;private final PlanningTaskAssignmentRepository assignments; public PersistentPlanningTaskAssignmentService(PlanningTaskRepository t,PlanningProjectMemberRepository m,PlanningTaskAssignmentRepository a){tasks=t;members=m;assignments=a;} public Mono<PlanningTaskAssignmentView> assign(UUID owner,UUID taskId,AssignPlanningTaskRequest r){return task(owner,taskId).flatMap(task->{if(task.projectId()==null)return Mono.error(new ConflictException("只有 Project 中的 Task 才能分配"));return members.findByProjectIdAndUserId(task.projectId(),r.assigneeId()).switchIfEmpty(Mono.error(new NotFoundException("Assignee 不是 Project 成员"))).then(assignments.findByTaskIdAndAssigneeId(taskId,r.assigneeId()).flatMap(x->Mono.<PlanningTaskAssignmentView>error(new ConflictException("Task 已分配给该成员"))).switchIfEmpty(assignments.save(new PlanningTaskAssignmentEntity(null,taskId,r.assigneeId(),owner,Instant.now())).map(this::view)));});} public Flux<PlanningTaskAssignmentView> list(UUID owner,UUID taskId){return task(owner,taskId).thenMany(assignments.findAllByTaskId(taskId)).map(this::view);} public Mono<Void> unassign(UUID owner,UUID taskId,UUID assigneeId){return task(owner,taskId).then(assignments.findByTaskIdAndAssigneeId(taskId,assigneeId).flatMap(assignments::delete).then()).then();} private Mono<PlanningTaskEntity> task(UUID owner,UUID id){return tasks.findById(id).filter(t->t.ownerId().equals(owner)).switchIfEmpty(Mono.error(new NotFoundException("Task 不存在")));} private PlanningTaskAssignmentView view(PlanningTaskAssignmentEntity x){return new PlanningTaskAssignmentView(x.id(),x.taskId(),x.assigneeId(),x.assignedBy(),x.createdAt());}}
